package com.visionerp.controller;
import com.visionerp.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/assistant") public class AssistantController {final AttendanceRepository a;final EmployeeRepository e;final VisitorRepository v;public AssistantController(AttendanceRepository a,EmployeeRepository e,VisitorRepository v){this.a=a;this.e=e;this.v=v;}@PostMapping("/ask")public Map<String,Object> ask(@RequestBody Map<String,String>b){String q=b.getOrDefault("question","").toLowerCase();LocalDate d=LocalDate.now();if(q.contains("absent")){long p=a.countByWorkDateAndStatus(d,"PRESENT"),l=a.countByWorkDateAndStatus(d,"LATE");return Map.of("answer","Today there are "+Math.max(0,e.countByActiveTrue()-p-l)+" employees without a PRESENT/LATE attendance record.","tool","get_attendance_summary");}if(q.contains("late"))return Map.of("answer","Today there are "+a.countByWorkDateAndStatus(d,"LATE")+" late arrivals.","tool","get_attendance_summary");if(q.contains("visitor"))return Map.of("answer","There are "+v.countByStatus("CHECKED_IN")+" visitors currently checked in.","tool","get_visitor_statistics");return Map.of("answer","I can answer attendance, absence, late-arrival, and visitor questions using authorized VisionERP data.","tool","help");}}
